};

// ---- KPI building blocks: figure block + mini column chart ----------
// figure(): title, big number + unit, delta tag and a caption line
const figure = (w, h, o) => {
  const g = card(w, h, { title: o.title, caption: o.caption, marker: o.marker });
  const big = Math.max(26, Math.min(38, w / 8.5));
  const y = 52 + big / 2;
  const num = fmt(o.value, o.dec ?? 0);
  g.push({
    type: 'text', silent: true,
    style: {
      x: 18, y, verticalAlign: 'middle',
      text: `{n|${num}}${o.unit ? `{u| ${o.unit}}` : ''}`,
      rich: {
        n: { fill: o.value == null ? T.faint : T.ink, fontSize: big, fontWeight: 600, fontFamily: FONT },
        u: { fill: T.muted, fontSize: Math.round(big * 0.42), fontWeight: 500, fontFamily: FONT, padding: [Math.round(big * 0.3), 0, 0, 0] },
      },
    },
  });
  if (o.delta) {
    const c = o.delta.good == null ? T.muted : o.delta.good ? T.good : T.bad;
    g.push({ type: 'text', silent: true, style: { x: 18, y: y + big / 2 + 12, text: o.delta.text, fill: c, fontSize: 11, fontWeight: 600, fontFamily: MONO, verticalAlign: 'middle' } });
    if (o.sub) g.push({ type: 'text', silent: true, style: { x: 18 + textW(o.delta.text, 11, 600, MONO) + 10, y: y + big / 2 + 12, text: o.sub, fill: T.muted, fontSize: 11, fontFamily: FONT, verticalAlign: 'middle', width: w * 0.55, overflow: 'truncate' } });
  } else if (o.sub) {
    g.push({ type: 'text', silent: true, style: { x: 18, y: y + big / 2 + 12, text: o.sub, fill: T.muted, fontSize: 11, fontFamily: FONT, verticalAlign: 'middle', width: w * 0.6, overflow: 'truncate' } });
  }
  return { g, bottom: y + big / 2 + 24 };
};

// columns(): tiny stacked column chart; stacks = [{ values, color }], highlight last
const columns = (x, y, w, h, stacks, { gap = 2, fadeLast = false, ref } = {}) => {
  const n = stacks[0]?.values.length || 0;
  if (!n || h < 8) return [];
  const tot = Array.from({ length: n }, (_, i) => stacks.reduce((s, st) => s + Math.max(0, st.values[i] || 0), 0));
  const max = Math.max(...tot, ref || 0, 1e-9);
  const bw = Math.max(1, (w - gap * (n - 1)) / n);
  const out = [];
  for (let i = 0; i < n; i++) {
    let base = y + h;
    stacks.forEach((st) => {
      const v = Math.max(0, st.values[i] || 0);
      const bh = (v / max) * h;
      if (bh > 0.2) out.push({ type: 'rect', silent: true, shape: { x: x + i * (bw + gap), y: base - bh, width: bw, height: bh, r: [1.5, 1.5, 0, 0] }, style: { fill: st.color, opacity: fadeLast && i === n - 1 ? 0.45 : 1 } });
      base -= bh;
    });
    if (!tot[i]) out.push({ type: 'rect', silent: true, shape: { x: x + i * (bw + gap), y: y + h - 1, width: bw, height: 1 }, style: { fill: T.track } });
  }
  if (ref != null) out.push({ type: 'line', silent: true, shape: { x1: x, y1: y + h - (ref / max) * h, x2: x + w, y2: y + h - (ref / max) * h }, style: { stroke: T.faint, lineDash: [2, 3], lineWidth: 1 } });
  return out;
};

// ---- panel: 03_battery.js ----
// KPI · Battery — state of charge ring, current mode, equivalent cycles (7 d)
const A = frame('A');
const t = A.col('time'); const soc = A.num('soc_pct'); const mw = A.num('bess_mw'); const dis = A.num('discharged_mwh');
const n = t.length;
const nowSoc = soc[n - 1];
const nowMw = mw[n - 1] ?? 0;
const mode = nowMw > 0.3 ? `Discharging ${fmt(nowMw, 1)} MW` : nowMw < -0.3 ? `Charging ${fmt(-nowMw, 1)} MW` : 'Idle';
const cycles = dis.reduce((s, v) => s + (v || 0), 0) / 80;
const modeColor = nowMw > 0.3 ? T.battery : nowMw < -0.3 ? T.export : T.muted;

return mount((w, h) => {
  const { g } = figure(w, h, {
    title: 'Battery', caption: '20 MW · 80 MWh', marker: T.battery,
    value: nowSoc, dec: 0, unit: '% SoC',
    sub: `${fmt(cycles, 1)} cycles in 7 days`,
  });
  g.push({ type: 'text', silent: true, style: { x: 18, y: h - 26, text: `● ${mode}`, fill: modeColor, fontSize: 12, fontWeight: 600, fontFamily: FONT, verticalAlign: 'middle' } });
  // ring gauge on the right
  const r = Math.min(h * 0.27, w * 0.16);
  const cx = w - 18 - r - 4, cy = h / 2 + 14;
  const frac = Math.max(0, Math.min(1, (nowSoc ?? 0) / 100));
  const start = -Math.PI / 2;
  g.push(
    { type: 'arc', silent: true, shape: { cx, cy, r, startAngle: 0, endAngle: Math.PI * 2 }, style: { stroke: T.track, lineWidth: 9, fill: 'none' } },
    { type: 'arc', silent: true, shape: { cx, cy, r, startAngle: start, endAngle: start + frac * Math.PI * 2 }, style: { stroke: { type: 'linear', x: 0, y: 0, x2: 1, y2: 1, colorStops: [{ offset: 0, color: T.wind }, { offset: 1, color: T.battery }] }, lineWidth: 9, lineCap: 'round', fill: 'none' } },
    { type: 'text', silent: true, style: { x: cx, y: cy - 3, text: nowMw > 0.3 ? '▼' : nowMw < -0.3 ? '▲' : '■', align: 'center', verticalAlign: 'middle', fill: modeColor, fontSize: 13, fontFamily: FONT } },
    { type: 'text', silent: true, style: { x: cx, y: cy + 13, text: `${fmt((80 * (nowSoc ?? 0)) / 100, 0)} MWh`, align: 'center', verticalAlign: 'middle', fill: T.muted, fontSize: 9.5, fontFamily: MONO } },
  );
  // 24 h SoC trace under the figure
  const pts = soc.slice(-24);
  if (pts.length > 1) {
    const x0 = 18, x1 = cx - r - 22, y0 = h - 62, y1 = h - 42;
    const line = pts.map((v, i) => [x0 + ((x1 - x0) * i) / (pts.length - 1), y1 - ((v || 0) / 100) * (y1 - y0)]);
    g.push({ type: 'polyline', silent: true, shape: { points: line, smooth: 0.2 }, style: { stroke: T.battery, lineWidth: 1.6, fill: 'none', opacity: 0.9 } });
  }
  return { backgroundColor: 'transparent', animation: false, graphic: g };
}, ['graphic']);

